/**
 * Knowledge Academy: 20 departments, each with Beginner / Intermediate / Advanced lessons.
 * Original introductory explanations. For deeper study, learners attach their own trusted
 * sources (Saved resources). No academic references are fabricated here.
 */
export type Level = 'Beginner' | 'Intermediate' | 'Advanced';
export const LEVELS: Level[] = ['Beginner', 'Intermediate', 'Advanced'];
export interface QuizQ { q: string; options: string[]; answer: number; why: string }
export interface Lesson {
  id: string; subjectId: string; subjectName: string; level: Level; title: string;
  explanation: string; example: string; exercise: string; quiz: QuizQ[]; cards: [string, string][]; minutes: number;
}
export interface Subject { id: string; name: string; icon: string; blurb: string; lessons: Lesson[] }

type L = [title: string, explanation: string, example: string, exercise: string, quiz: [string, string[], number, string][], cards: [string, string][]];

