export const SUBJECTS: Subject[] = RAW.map((s) => ({
  id: s.id, name: s.name, icon: s.icon, blurb: s.blurb,
  lessons: s.levels.map((l, i) => {
    const [title, explanation, example, exercise, quiz, cards] = l;
    return {
      id: `${s.id}-${i + 1}`, subjectId: s.id, subjectName: s.name, level: LEVELS[i], title, explanation, example, exercise,
      quiz: quiz.map(([q, options, answer, why]) => ({ q, options, answer, why })), cards,
      minutes: 10 + i * 5,
    };
  }),
}));

export const ALL_LESSONS = SUBJECTS.flatMap((s) => s.lessons);
export const getSubject = (id: string) => SUBJECTS.find((s) => s.id === id);
export const getLesson = (id: string) => ALL_LESSONS.find((l) => l.id === id);

export function searchLessons(q: string) {
  const words = q.toLowerCase().split(/\W+/).filter((w) => w.length > 2);
  if (!words.length) return [];
  return ALL_LESSONS.map((l) => {
    const hay = `${l.title} ${l.explanation} ${l.cards.map((c) => c.join(' ')).join(' ')}`.toLowerCase();
    const score = words.reduce((n, w) => n + (hay.includes(w) ? (l.title.toLowerCase().includes(w) ? 3 : 1) : 0), 0);
    return { l, score };
  }).filter((x) => x.score > 0).sort((a, b) => b.score - a.score).map((x) => x.l);
}
